async function createAuthTuple(wallet, chainId, contractAddress, nonce) {
    let authNonce = nonce + 1; // Increment nonce by 1 for the next transaction
    const chainIdHex = "0x" + chainId.toString(16);
    const nonceHex = "0x" + authNonce.toString(16);
    const addressHex = contractAddress; // Should already be a hex string like "0x..."

    // Step 1: RLP encode [chain_id, address, nonce]
    const rlpEncoded = RLP.encode([chainIdHex, addressHex, nonceHex]);

    // Step 2: Prepend MAGIC (0x05)
    const magic = Buffer.from('05', 'hex');
    const messageBuffer = Buffer.concat([magic, rlpEncoded]);

    // Step 3: Hash to get the message
    const message = ethers.keccak256(messageBuffer);

    // Step 4: Sign the message
    const signature = await wallet.signMessage(ethers.getBytes(message));
    const sig = ethers.Signature.from(signature);
    const yParity = sig.v - 27; // Converts v to 0 or 1

    // Step 5: Return the tuple
    return [
        chainIdHex,
        addressHex,
        nonceHex,
        yParity,
        sig.r,
        sig.s
    ];
}
```

